  VALUES 
    (812::BIGINT, 'La primera profe de mate que tuve en la U, y es excelente! No perdí el interés ni una sola vez y aprendí cosas que me sirvieron para CDI. Si usted es responsable y esta comprometido a pasar mate general, lleve con ella, pero si no dudo mucho que pasé.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'd58db4386ffad3e891ed72d8ade792b3d9a2568bc35aab2e5b65c71fa10e6a54'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Muy buena profesora, antes de tomar el curso con ella, me decían que no era muy buena y que se enredaba pero es solo de prestar atención, me pareció excelente, sin duda volvería a llevar el curso con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '427bd757237a41f5ad42eca8ada2f020d252ec9ba4f510fe34d0b19d7b0cf9a4'::TEXT, ARRAY[563, 1018]::BIGINT[]),
