    (812::BIGINT, 'Es buena profe, explica muy bien. Me atrevo a decir que es una de las mejores en el area de matemática para CDI... Cuando ve que la mayoría van quedados, hace quiz el pareja; "A veces mijo, a veces, no siempre". Postdata: Aparte de todo eso; está guap4, dichoso Ernesto que topó con suerte :D'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2024-02-27T00:00:00+00:00'::TIMESTAMPTZ, '518f773974ff3e28c9a5382e2c52aa4f25832247f7c5cfef763595a0d56976a5'::TEXT, ARRAY[605]::BIGINT[]),
    (812::BIGINT, 'El curso es difícil, hay que ponerle mucho desde el principio porque el curso es colegiado con Cartago. La profe explica bien y si faltas pierdes materia y cuesta ponerse al día'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Exámenes retadores']::TEXT[], '2024-01-18T00:00:00+00:00'::TIMESTAMPTZ, '54f9d5e7c7c634976857b975d63086ac0f69881033fa6e4684c36f25aeced26d'::TEXT, ARRAY[563]::BIGINT[]),
