    (812::BIGINT, 'No puede resolver ejercicios cátedra y los deja deja de tarea moral para los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'e097a20aec48e85b8755ee498e7c3690dd6196b249f18a437bc116e61d5ed0a3'::TEXT, ARRAY[605]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '232f5557b8a4245fcb59c29832c0a0410f02a96703b10dabcc3a1f191a3173aa'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'La profesora Jessica es muy atenta, ella se esfuerza porque los estudiantes aprendan. Enseña sobre valores que los van a ayudar no solo con el curso sino con su vida profesional. La recomendaría a ojos cerrados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4a7f7f54bea1c66c0cdad2bfba86519673f657147b623c160ea347a9ab78576c'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'La profe explica bastante bien, sólo que hay que asistir a clases, ya que a veces hace cuices sorpresa que dan puntos extras.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '273643b6d9792f682fe030d9ec673bc10313bb28439e83c21e9201a14faeae41'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'No la recomiendo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '664f54e9aafe135e4e31a80209db38802661360b8a49e18bb1e8a63f21445095'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Buena enseñando, las tareas y exámenes parecidos a la práctica, responde consultas al Telegram a veces, pero humilla a los estudiantes, ignora correos (para justificaciones de exámenes o trabajos). Varios estudiantes mienten en esta plataforma para caerle bien a ella (ella hace que escriban aquí).'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-03-14T00:00:00+00:00'::TIMESTAMPTZ, 'c0528c027c35d497e06c1f6b6529c1f3c56370640eb2e41377e1815cbb0058fa'::TEXT, ARRAY[2444]::BIGINT[]),
    (812::BIGINT, 'Explica bastante claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2021-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'eb274087e9bc1d8c3a7f83a07fbcb598be0ae7c63b8c62c3b46e30f6c22c58c1'::TEXT, ARRAY[1018]::BIGINT[]),
    (812::BIGINT, 'Aveces se desvia del tema pero no lo veo mal, en general creo que es una buena profesora ya que muestra interés por que el estudiante comprenda y aprenda, si he notado que es como un poco distraída, por último me gustaría decirle que su historia me inspira no darme por vencida, Gracias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-10-06T00:00:00+00:00'::TIMESTAMPTZ, 'ca68a131d58b543bda2b62c46445768eba1de0b11a16fed228e758e263334c6b'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'La mejor maestra que conozco nos enseña al 100% súper recomendada nos entiende y nos brinda todas las opciones para entender la materia .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '4a9fd1e980d3b26e73c3c4905d69daff8749dbe133411ef1e37e71b82bfaeb55'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '16531d7ae6d51b945a30d14aea091178c8b1d027ce8eae0383d62fc2696bbc3f'::TEXT, ARRAY[2439]::BIGINT[]),
    (812::BIGINT, 'En clases virtuales uno sabe que siempre va a tener las clases grabadas, (este curso en debería quedar mixto (virtual presencial), explica bien. debería usar más ejercicios de libro oficial para estudiar solo con eso y los videos y dejar las tareas con más plazo para hacerlas después de tutorías.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '9a08d1313d39cf7490b52ad559ee9586e811e74458d610954e9cfded7ed9b03c'::TEXT, ARRAY[2439]::BIGINT[]),
    (812::BIGINT, 'En modalidad virtual me pareció buena, es amistosa y se preocupa por los estudiantes. Ella hacía ejercicios de exámenes viejos, explicaba la materia si era necesaria pero no era su obligación ya que nosotros debíamos leer las consignas (si uno no lo leía por x motivo le explicaba a uno chill)'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'db5d313d5a98215941837a9bf76f6008d13c56ab3a60e846fe3ad0f2c6a5ae7a'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'a890c915c23c55aaecfcfc32b08b646a4abe68bfaa3b4625540ffa9d2de43d19'::TEXT, ARRAY[1018, 563, 2439]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '326fe41b6926f4a0acc05cdae9e87d86a362735c4237be0c43273b8abc5d7575'::TEXT, ARRAY[2439]::BIGINT[]),
    (812::BIGINT, 'Usted es demasiado grosera, esa es la razón por la que sus estudiantes no le preguntan, tome en cuenta que no hacemos consultas para que nos haga ver estúpidos. Excelente profesora, pero debería mejorar esas cosas.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '27da15017b7ea25adee41d30d3037872b4136dc5750a3e6c1197f8f4bf84757a'::TEXT, ARRAY[1018, 563, 2439]::BIGINT[]),
    (812::BIGINT, 'Hay que estar atento a los ejercicios que va realizando ya que por lo general deja perdidos los menos (-) o copia mal las ecuaciones. Pero siempre se autorrige, o la corrigen. Da todas las clases que debe, y explica de manera muy amplia. Nunca contesta la mensajes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2021-10-04T00:00:00+00:00'::TIMESTAMPTZ, '3e0c69f3238d6c3d396ab536908045e8b87a581b7dba3599c3a3cc7db0441d43'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'Explica de una manera muy clara y sensilla de entender, para mi es una de las mejores profesoras!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-10-04T00:00:00+00:00'::TIMESTAMPTZ, '0cdd3168c9b52964519752f1769e545fad529b85c21203839539624fb215439f'::TEXT, ARRAY[935]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-04T00:00:00+00:00'::TIMESTAMPTZ, '475d04f1f9e4db302984e034f4de6261e975e487788d226a1c61a15502eadc47'::TEXT, ARRAY[2439]::BIGINT[]),
    (812::BIGINT, 'La profe explica bastante claro, siempre hace pasos intermedios, no da por hecho que uno sabe todo, entonces empieza desde el inicio y hace paréntesis con materia de cursos anteriores.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f957639c2179bb20a16dbaf19b1875a475ceff4ada8a17ede109d87ad30b509a'::TEXT, ARRAY[2439]::BIGINT[]),
    (812::BIGINT, 'Es bastante clara al explicar pero me gustaría que hiciéramos un poco más de ejercicios!'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'eb3c787dcafa8b741c309949594b16c6ce9352c5de6bee68cbaf435808367fb6'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (812::BIGINT, 'Excelente profesora.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-20T00:00:00+00:00'::TIMESTAMPTZ, '8b9cf5071247d5dae8b80b4e4d722a5aa792c4d5b461b029ed82f74851c93136'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
