    (812::BIGINT, 'Excelente profesora, explica bien y a pesar de que deja muchas tareas, se pueden resolver si se pone atención en su clase y se toman apuntes'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, '88207e34b4d74ebe9651573a4e2dbc450b2d452c36368ad0626fc5d79a77b61e'::TEXT, ARRAY[1018, 563, 2439]::BIGINT[]),
