    (812::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '0e124930f50b524a3ea12ae5af08b876d50c810f7a9bc2212a1d2bca0058ce33'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Explica de una forma muy sencilla, lo que facilita la comprensión de los temas, además, no se salta pasos en los ejercicios para que las personas a las que se les dificulta logren entender todo bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '3ead38ce3e759575f33b70436af9b2ae5189a7b24f90e30a0cfc25d33471f49f'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Explica con claridad y las veces necesarias, ayuda bastante y interactúa de forma agradable con los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c6c134034ab5fe03cd037316712170cc347c22ffe0d834e8349d35ca73de7c27'::TEXT, ARRAY[563]::BIGINT[]),
