    (812::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7476dcd157f398817e600a1ecbaa8893525111b72f3f2aa2327fbe86739b0954'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Muy buen profesor, nos transmite esa inspiración para querer seguir adelante ante las dificultades, explica hasta que uno le entiende, además es atento y nos brinda el apoyo para uno lograr terminar el curso de la mejor manera'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '1c78f52f4b4f09ca4293da0970893da36b54923bb4f43025907a04d590107238'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'be15c349ab9d03261389ee1a539f8c0c311796b9482f679a064e83995ed6b58d'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'No tengo quejas, ya que las clases en la mayoría del tiempo se logra entender lo que explica, además para ser apoyo la pulseaba bastante, recomendando utilizar las horas consulta y si hay dudas, la pulsea para que uno quede claro Muy buena profe la verdad y vacilona, solo por vago se quedan con ella'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'c1b83fdfb460254dd3682ca11b3bd87c1b75ea252f9491ff6c84801317d92c3d'::TEXT, ARRAY[563]::BIGINT[]),
    (812::BIGINT, 'Es una excelente profe, estoy muy agradecido por su paciencia y pasión que ella tiene para dar la clase. Ella es muy amable, uno puede preguntar sin miedo o vergüenza ella le aclara la duda de una forma muy linda y amable, sinceramente estoy feliz de haber tenido clases con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '56cd76674e7068c3a6e44ac228d1bb7a335624fde0d4b5b8890e1f1cb4455c9d'::TEXT, ARRAY[563]::BIGINT[]),
