    (812::BIGINT, 'Excelente profe se preocupa por que el estudiante comprenda la materia a la perfección antes de seguir avanzando, la asistencia a clases es muy importante, facilita bastante practica para los parciales, súper recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '3cb68c671147aa1869966ad022f7f6d024962e450a0ab36572779ad37d374764'::TEXT, ARRAY[563]::BIGINT[]),
